python3 - "$snapshot" <<'PY'
import json
import sys
from pathlib import Path
root = Path(sys.argv[1])
files = records = blanks = 0
errors = []
for path in root.rglob('*.jsonl'):
    with path.open(encoding='utf-8') as stream:
        for line_number, line in enumerate(stream, 1):
            if not line.strip():
                blanks += 1
                continue
            try:
                json.loads(line)
                records += 1
            except Exception as exc:
                errors.append((str(path.relative_to(root)), line_number, type(exc).__name__))
    files += 1
print(f'JSONL files={files} records={records} blank_lines={blanks} invalid_nonblank={len(errors)}')
for path, line, kind in errors[:20]:
    print(f'{path}:{line}: {kind}')
raise SystemExit(bool(errors))
